import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { content1Schema, type Content1 } from "./unions/content1.js";
import { functionCallSchema, type FunctionCall } from "./unions/function-call.js";
import { refusal1Schema, type Refusal1 } from "./unions/refusal1.js";
import { role2Schema, type Role2 } from "./unions/role2.js";
import { toolCallsSchema, type ToolCalls } from "./unions/tool-calls.js";

/** A chat completion delta generated by streamed model responses. */
export type ChoiceDelta = {
  content?: Content1;
  functionCall?: FunctionCall;
  refusal?: Refusal1;
  role?: Role2;
  toolCalls?: ToolCalls;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const choiceDeltaSchema: Schema<ChoiceDelta> = s.object<ChoiceDelta>(
  {
    content: s.optional(s.lazy(() => content1Schema)),
    functionCall: s.optional(s.lazy(() => functionCallSchema)),
    refusal: s.optional(s.lazy(() => refusal1Schema)),
    role: s.optional(s.lazy(() => role2Schema)),
    toolCalls: s.optional(s.lazy(() => toolCallsSchema)),
    _keysMap: {
      functionCall: "function_call",
      toolCalls: "tool_calls",
    },
  },
  { additionalProperties: s.json() },
);
